    own(a, "state") === state &&
    own(a, "source") === source &&
    fields.every((k, i) => own(a, k) === values[i]) &&
    sourceKeys.every((k, i) => own(source, k) === sourceValues[i]) &&
    Reflect.ownKeys(state).length === keys.length &&
