        !!factory?.get &&
        !!current &&
        factory.get === current.get &&
        factory.set === current.set &&
        factory.enumerable === current.enumerable &&
        factory.configurable === current.configurable
      );
    })
  )
    throw new Error("demon_hunter_unreadable_world");
}
