    t &&
    !t.request &&
    validWindow(t) &&
    p.actorId === t.actorId &&
    p.phase === Phase.Night &&
    p.context.day === t.day &&
    p.context.stage ===
      (t.kind === "knife" && t.binding.activeNight?.capture.owner === "ordinary_pack"
        ? "wolf_vote"
